<template>
  <view :class="['app-frame','page-'+view,{'is-practicing':view==='practice'&&activeMode==='vocabulary','is-oral':activeMode==='oral','is-grammar':activeMode==='grammar'}]">
    <Transition name="drawer-slide"><view v-if="drawerOpen" class="drawer-shade" @click="closeDrawerOnBlank"><aside class="sidebar drawer-panel" role="dialog" aria-modal="true" aria-label="导航菜单 / Navigation"><button hover-class="none" class="icon-button drawer-close" @click="drawerOpen=false" aria-label="关闭菜单 / Fermer le menu"><Icon name="close" /></button><view class="brand"><image class="brand-mark app-icon" :src="appIcon" mode="aspectFit" alt="启航法语" /><view><text class="brand-title">启航法语</text><text class="brand-sub">Cap sur le français</text></view></view><text v-if="!studyView" class="rail-caption">VOTRE PETIT RENDEZ-VOUS</text><nav class="rail-nav"><button hover-class="none" v-for="n in navigation" :key="n.id" :class="['nav-item',{active:navActive===n.id}]" @click="navigate(n.id)"><Icon :name="n.icon" /><Bi :zh="n.zh" :fr="n.fr" /><view v-if="n.id==='notebook'&&notebookHasBadge" class="practice-badge" aria-label="有待练词 / À pratiquer" /></button></nav><view v-if="!studyView" class="rail-note"><view class="mini-book">F<span>1</span></view><text lang="fr">{{ quotes[sidebarQuote].fr }}</text><text class="muted">{{ quotes[sidebarQuote].zh }}</text><text class="quote-author">{{ quotes[sidebarQuote].author }}</text></view></aside></view></Transition>
    <view class="main-area">
      <header class="topbar"><button hover-class="none" class="icon-button menu-toggle" :aria-expanded="drawerOpen" @click="drawerOpen=true" aria-label="打开导航菜单 / Ouvrir le menu"><Icon name="menu" /></button><view class="mobile-brand"><image class="brand-mark small app-icon" :src="appIcon" mode="aspectFit" alt="启航法语" /><text>启航法语</text></view><view class="desktop-caption"><text>启航法语</text><text>Cap sur le français</text></view><view class="topbar-actions"><button hover-class="none" class="mode-switch-button" @click="modeDrawerOpen=true" :aria-expanded="modeDrawerOpen"><Icon name="modes" /><Bi zh="模式" fr="Modes" small /></button><text v-if="!studyView" class="date-label">{{ dateLabel }}</text></view></header>
      <Transition :name="view==='lessons'?'lesson-entrance':'page-fade'" mode="out-in">
      <main v-if="activeMode==='oral'" key="oral" class="content oral-content"><OralMode @notice="notice" /></main>
      <main v-else-if="activeMode==='grammar'" key="grammar" class="content grammar-content"><GrammarMode @notice="notice" /></main>
      <main v-else :key="view+(view==='lesson'?':'+previewLessonKey:['recite','practice'].includes(view)?':'+selectedKey:'')" class="content" :class="{ 'practice-content': view==='practice' }">
        <view v-if="fatal" class="glass empty-state"><Icon name="info" /><Bi zh="本地记录暂时无法读取" fr="Les données locales sont inaccessibles." /><text>{{ fatal }}</text><button hover-class="none" class="button primary" @click="load"><Bi zh="重试" fr="Réessayer" /></button></view>
        <template v-else-if="!ready"><view class="glass empty-state"><view class="spinner" /><Bi zh="正在打开学习空间" fr="Ouverture de votre espace…" /></view></template>
        <template v-else-if="view==='books'"><HomeDashboard :book-title="selectedBookTitle" :lesson-id="currentPackage?.lesson.id" :total="currentStats?.total||0" :completed="currentStats?.completed||0" :today="todayCount" :due="dueReviewCount" :review-in-progress="hasReviewInProgress" :busy="busy" :last-label="lastPractice?.label" @book="view='manuals'" @lesson="chooseLesson" @recite="openRecitation()" @practice="startLearningPractice" @review="startTodayReview" @resume="resumeLastPractice" /></template>
        <template v-else-if="view==='manuals'"><view class="picker-heading"><button hover-class="none" class="icon-button back-control" @click="navigate('books')" aria-label="返回 / Retour"><Icon name="back" /></button><view class="page-heading"><h1>教材<span>Manuels</span></h1></view></view><BookPicker :selected="selectedBookId" :lessons="lessons.length" @select="selectBook" /></template>
        <template v-else-if="view==='lessons'"><view class="picker-heading"><button hover-class="none" class="icon-button back-control" @click="navigate('books')" aria-label="返回 / Retour"><Icon name="back" /></button><view class="page-heading"><h1>Lesson<span>{{ selectedBookTitle||'Inspire 1' }}</span></h1></view></view><LessonPicker :entries="lessonEntries" :selected="selectedKey" @select="selectLesson" @preview="openLesson" @pin="toggleLessonPin" @reset="requestLessonReset" /></template>
        <template v-else-if="view==='lesson' && currentPackage">
          <button hover-class="none" class="back-link" @click="navigate('lessons')"><Icon name="back" /><Bi zh="返回课次" fr="Toutes les leçons" inline /></button><view class="page-heading"><view><text class="eyebrow">INSPIRE 1 · {{ currentPackage.lesson.id }}</text><h1>{{ currentPackage.lesson.title.split(' · ')[0] }}<span>{{ currentPackage.lesson.title.split(' · ')[1] || '单词 · Vocabulaire' }}</span></h1></view><button hover-class="none" class="help-inline" @click="help='learning'" aria-label="学习帮助 / Aide"><text>?</text></button></view>
          <view class="lesson-summary glass"><view v-for="stat in [{key:'practice',zh:'待学',fr:'à apprendre'},{key:'review',zh:'复习本',fr:'à réviser'},{key:'known',zh:'已会',fr:'acquis'}]" :key="stat.key"><strong>{{ currentStats[stat.key] }}</strong><Bi :zh="stat.zh" :fr="stat.fr" small /></view></view>
          <view class="search-row"><view class="search-box"><Icon name="search" /><input :adjust-position="false" v-model="search" placeholder="搜索本课单词 / Rechercher dans la leçon" aria-label="搜索本课单词 / Rechercher" /></view><text class="muted">{{ visibleWords.length }} 词 · mots</text></view>
          <view v-if="visibleWords.length" class="lesson-word-list glass"><view v-for="word in visibleWords" :key="word.id"  :class="['lesson-word-row',{'is-learned':getProgress(data,currentPackage,word).notebook!=='practice'}]"><button hover-class="none" class="lesson-word-main" @click="openWordPreview(currentPackage,word)"><text lang="fr">{{ word.forms.map(f=>displayForm(word,f)).join(' / ') }}</text><text class="pos">{{ word.sourcePos||word.pos }}</text><Icon name="arrow" /></button><button hover-class="none" :class="['icon-button','favorite',{marked:data.favorites[wordKey(currentPackage,word)]}]" @click="favorite(word)" :aria-label="data.favorites[wordKey(currentPackage,word)]?'取消收藏 / Retirer des favoris':'收藏 / Ajouter aux favoris'"><Icon name="heart" /></button></view></view>
          <view v-if="!visibleWords.length" class="empty-state glass"><Bi zh="没有找到这个词" fr="Aucun mot trouvé." /></view>
          <view class="lesson-management"><button hover-class="none" class="text-button" :class="{marked:data.pinnedLessons?.[packageKey(currentPackage)]}" @click="toggleLessonPin(currentPackage)"><Icon name="star" /><Bi zh="重点 Lesson" fr="Prioritaire" small /></button><button v-if="!currentStats.practice" hover-class="none" class="text-button" @click="requestLessonReset(currentPackage)"><Icon name="repeat" /><Bi zh="一键放回" fr="Recommencer" small /></button></view>
          <view class="lesson-dock glass learning-choice-dock"><button hover-class="none" class="button primary" :disabled="busy" @click="openRecitation()"><Icon name="cards" /><Bi zh="开始背诵" fr="Mémoriser" /></button><button hover-class="none" class="button secondary" :disabled="busy" @click="startLearningPractice"><Icon name="edit" /><Bi zh="直接练习" fr="Pratiquer" /></button></view>
        </template>
        <template v-else-if="view==='recite'&&currentPackage"><view class="recitation-top"><button hover-class="none" class="icon-button back-control" @click="navigate('books')" aria-label="返回首页 / Accueil"><Icon name="back" /></button><view><text>{{ currentPackage.lesson.id }}</text><Bi zh="背诵" fr="Mémoriser" small /></view><text class="muted">{{ currentStats.completed }} / {{ currentStats.total }}</text><button v-if="!currentStats.practice" hover-class="none" class="icon-button" @click="requestLessonReset(currentPackage)" aria-label="一键放回 / Recommencer"><Icon name="repeat" /></button></view><RecitationPanel :key="selectedKey" :pkg="currentPackage" :data="data" :playing="playing" :busy="busy" @audio="play" @audio-stop="stopPlaying" @detail="openWordPreview(currentPackage,$event)" @practice="startLearningPractice" /></template>
        <template v-else-if="view==='practice' && currentPackage && currentSession">
          <view class="practice-top"><button hover-class="none" class="icon-button back-control" @click="backFromPractice" aria-label="返回 / Retour"><Icon name="back" /></button><view class="practice-location"><text>{{ currentSession.mode==='review'?'复习 · Révision':currentSession.mode==='errors'?'错题 · Erreurs':currentSession.mode==='favorites'?'收藏 · Favoris':currentPackage.lesson.id }}</text><text class="muted">{{ currentSession.mode==='review'?'混合词汇 · Mots mélangés':currentSession.mode==='errors'?'错题专练 · Correction':currentSession.mode==='favorites'?'收藏专练 · Entraînement':currentSession.mode==='direct'?'单词专练 · Pratique':'学习 · Apprentissage' }}</text></view><text class="practice-count">{{ overallProgress.completed }} / {{ overallProgress.total }}</text><button hover-class="none" class="icon-button" @click="help='learning'" aria-label="练习帮助 / Aide"><Icon name="info" /></button></view>
          <view class="session-progress"><view :style="{width:overallProgress.percent+'%'}" /></view>
          <view v-if="currentSession.phase==='done'" class="completion glass">
            <view class="completion-icon"><Icon name="check" /></view><h1>{{ lessonFinished?'本课完成':'本轮完成' }}<span>{{ lessonFinished?'Leçon terminée':'Session terminée' }}</span></h1>
            <view class="completion-stats"><view><strong>{{ currentSession.doneWords.length }}</strong><Bi zh="已完成" fr="mots terminés" small /></view><view><strong>{{ currentSession.stats.attempts?Math.round(currentSession.stats.correct/currentSession.stats.attempts*100)+'%':'—' }}</strong><Bi zh="正确率" fr="réussite" small /></view></view>
            <view v-if="newKnownEntries.length" class="new-known-summary"><Bi :zh="`新加入已会本 · ${newKnownEntries.length}`" fr="Nouveaux acquis" small /><button v-for="entry in newKnownEntries" :key="wordKey(entry.p,entry.w)" hover-class="none" @click="openWordPreview(entry.p,entry.w)"><text lang="fr">{{ entry.w.forms.map(f=>displayForm(entry.w,f)).join(' / ') }}</text><text>{{ entry.w.meanings.join('；') }}</text><Icon name="arrow" /></button></view>
            <view class="completion-actions"><button hover-class="none" class="button secondary back-action" @click="backFromPractice"><Icon name="back" /><Bi zh="返回" fr="Retour" small /></button><button hover-class="none" v-if="currentSession.pending.length" class="button primary" :disabled="busy" @click="continuePractice"><Icon name="arrow" /><Bi zh="继续练习" fr="Continuer" small /></button><button hover-class="none" v-else-if="currentSession.mode==='review'" class="button primary" @click="navigate('books')"><Bi zh="首页" fr="Accueil" small /><Icon name="check" /></button><button hover-class="none" v-else-if="lessonFinished" class="button primary" :disabled="busy" @click="startNextLesson"><Bi :zh="nextLesson?'下一课时':'选择 Lesson'" :fr="nextLesson?'Leçon suivante':'Choisir une leçon'" small /><Icon name="arrow" /></button><button hover-class="none" v-else class="button primary" @click="navigate('notebook')"><Icon name="notebook" /><Bi zh="返回词本" fr="Carnets" small /></button></view>
          </view>
          <PracticePanel v-else-if="activeWord" ref="practicePanel" :key="currentSession.id" :pkg="currentPackage" :source-pkg="activeSourcePackage" :session="currentSession" :word="activeWord" :form="activeForm" :favorite="!!data.favorites[wordKey(currentPackage,activeWord)]" :playing="playing" :busy="busy" :motion="data.settings.wordMotion" :article-mode="data.settings.articleMode||'choice'" @answer="answer" @next="next" @hint="hint" @retry-hint="retryHint" @known="markKnown" @favorite="favorite" @audio="play" @audio-stop="stopPlaying" />
        </template>
        <template v-else-if="view==='notebook'">
          <view class="page-heading"><view><text class="eyebrow">LES MOTS QUI RESTENT</text><h1>你的词本<span>Chaque mot a sa place.</span></h1></view><button hover-class="none" class="help-inline" @click="help='notebook'" aria-label="词本帮助 / Aide"><text>?</text></button></view>
          <view class="tabs notebook-tabs"><button hover-class="none" v-for="tab in notebookTabs" :key="tab.id" :class="{active:notebookTab===tab.id}" @click="notebookTab=tab.id"><Bi :zh="tab.zh" :fr="tab.fr" small /><view v-if="practiceBadges[tab.id]?.pending" class="practice-badge" aria-label="有待练词 / À pratiquer" /></button></view>
          <view v-if="notebookTab==='review'" class="glass daily-review-dock"><Bi :zh="dueReviewCount+' 个到期词'" :fr="dueReviewCount+' mots à revoir'" /><button hover-class="none" class="button primary" :disabled="busy||(!dueReviewCount&&!hasReviewInProgress)" @click="startTodayReview"><Icon name="repeat" /><Bi :zh="hasReviewInProgress?'继续复习':'开始复习'" :fr="hasReviewInProgress?'Reprendre':'Réviser'" small /></button></view>
          <view v-if="notebookTab==='errors'" class="glass errors-practice-dock"><button hover-class="none" class="toggle-row" @click="setSetting('errorAutoRemove',data.settings.errorAutoRemove===false)"><Bi zh="复习两次后移出" fr="Retirer après 2 révisions" small /><view :class="['toggle',{on:data.settings.errorAutoRemove!==false}]" /></button><button hover-class="none" class="button primary" :disabled="busy||(!errorWordCount&&!hasErrorsInProgress)" @click="startErrors"><Icon name="repeat" /><Bi :zh="hasErrorsInProgress?'继续错题':'练习错题'" :fr="hasErrorsInProgress?'Reprendre':'Corriger'" small /><view v-if="practiceBadges.errors?.pending" class="practice-badge" aria-label="有待练错题 / Erreurs à réviser" /></button></view>
          <view v-if="notebookTab==='favorites'" class="glass daily-review-dock"><Bi :zh="favoriteWordCount+' 个收藏词'" :fr="favoriteWordCount+' mots favoris'" /><button hover-class="none" class="button primary" :disabled="busy||(!favoriteWordCount&&!hasFavoritesInProgress)" @click="startFavorites"><Icon name="repeat" /><Bi :zh="hasFavoritesInProgress?'继续练习':'练习收藏'" :fr="hasFavoritesInProgress?'Reprendre':'Pratiquer'" small /></button></view>
          <view class="search-box notebook-search"><Icon name="search" /><input :adjust-position="false" v-model="search" placeholder="搜索词本 / Rechercher un mot" /></view>
          <Transition name="panel-switch" mode="out-in"><view :key="notebookTab" class="notebook-panel"><view v-if="!notebookEntries.length" class="empty-state glass"><view class="empty-icon"><Icon name="notebook" /></view><Bi zh="这里还没有单词" fr="Aucun mot pour le moment" /><button hover-class="none" class="button secondary" @click="chooseLesson"><Bi zh="选择 Lesson" fr="Choisir une leçon" /></button></view>
            <view v-else class="glass review-word-list" :class="{'compact-review':notebookTab==='review'}"><template v-for="(entry,index) in notebookEntries" :key="wordKey(entry.p,entry.w)"><view v-if="notebookTab==='errors'?entry.errorDoneToday&&(index===0||!notebookEntries[index-1].errorDoneToday):notebookTab==='favorites'&&entry.practiceCount>0&&(index===0||notebookEntries[index-1].practiceCount===0)" class="practiced-divider"><Bi :zh="notebookTab==='errors'?'今日已复习':'已专练'" :fr="notebookTab==='errors'?'Révisés aujourd’hui':'Déjà pratiqués'" inline small /></view><view class="review-word-row" :class="{'reviewed-today':notebookTab==='errors'&&entry.errorDoneToday}"><button hover-class="none" class="notebook-entry-main" @click="reviewDetail=entry"><view class="notebook-word-label"><text lang="fr">{{ entry.w.forms.map(f=>displayForm(entry.w,f)).join(' / ') }}</text><text class="entry-lesson">{{ entry.p.lesson.id }}</text></view><view class="review-entry-meta"><text class="pos">{{ entry.w.sourcePos||entry.w.pos }}</text><template v-if="notebookTab==='review'"><Bi :zh="'已学习 '+studyDays(data,entry.p,entry.w,currentDate)+' 天'" :fr="'Jour '+studyDays(data,entry.p,entry.w,currentDate)" small /><Bi :zh="reviewCountdown(entry)" :fr="reviewCountdown(entry,true)" small /></template><template v-if="notebookTab==='errors'"><Bi :zh="'错误 '+entry.errorCount+' 次'" :fr="entry.errorCount+' erreurs'" small /><Bi :zh="'复习 '+entry.practiceCount+' 次'" :fr="entry.practiceCount+' révisions'" small /></template><Bi v-else-if="notebookTab==='favorites'" :zh="'专练 '+entry.practiceCount+' 次'" :fr="entry.practiceCount+' entraînement'+(entry.practiceCount===1?'':'s')" small /></view><Icon name="arrow" /></button><button hover-class="none" :class="['icon-button','favorite',{marked:data.favorites[wordKey(entry.p,entry.w)]}]" @click="favorite(entry.w,entry.p)" :aria-label="data.favorites[wordKey(entry.p,entry.w)]?'取消收藏 / Retirer des favoris':'收藏 / Favoris'"><Icon name="heart" /></button></view></template></view>
          </view></Transition>
        </template>
        <template v-else-if="view==='activity'">
          <view class="page-heading activity-heading"><view><text class="eyebrow">LES PETITS PROGRÈS</text><h1>每一天，都算数。<span>Votre chemin, jour après jour.</span></h1></view></view><view class="activity-stats"><view class="glass stat-card"><strong>{{ todayCount }}</strong><Bi zh="今日完成词数" fr="mots aujourd’hui" /></view><view class="glass stat-card"><strong>{{ shareStats.total }}</strong><Bi zh="累计背词" fr="mots appris" /></view><view class="glass stat-card"><strong>{{ Object.keys(data.activity).filter(k=>data.activity[k].words.length).length }}</strong><Bi zh="学习天数" fr="jours d’apprentissage" /></view></view><StudyCalendar :activity="data.activity" :library="data.library" @word="openWordPreview($event.p,$event.w)" />
        </template>
        <template v-else-if="view==='settings'">
          <view class="page-heading"><h1>设置<span>Réglages</span></h1><button hover-class="none" class="button secondary compact" @click="shareOpen=true"><Icon name="upload" /><Bi zh="分享" fr="Partager" small /></button></view>
          <view class="settings-panel-tabs"><button hover-class="none" v-for="tab in settingsTabs" :key="tab.id" :class="{active:settingsSection===tab.id}" @click="settingsSection=tab.id"><Icon :name="tab.icon" /><Bi :zh="tab.zh" :fr="tab.fr" small /></button></view>
          <Transition name="panel-switch" mode="out-in"><view :key="settingsSection" class="settings-section"><section v-if="settingsSection==='study'" class="glass settings-card"><view class="setting-row"><Bi zh="每轮词数" fr="Mots par série" small /><text>5</text></view><button hover-class="none" class="toggle-row" @click="setSetting('shuffleLearning',!data.settings.shuffleLearning)"><Bi zh="课内乱序学习" fr="Mélanger la leçon" small /><view :class="['toggle',{on:data.settings.shuffleLearning}]" /></button><view class="setting-stack"><Bi zh="名词冠词" fr="Articles des noms" small /><view class="segments"><button hover-class="none" v-for="item in [{id:'choice',zh:'选择冠词',fr:'Choisir'},{id:'typed',zh:'自行填写',fr:'Écrire'}]" :key="item.id" :class="{active:(data.settings.articleMode||'choice')===item.id}" @click="setSetting('articleMode',item.id)"><Bi :zh="item.zh" :fr="item.fr" small /></button></view></view><view class="setting-stack"><Bi zh="切词动效" fr="Animation" small /><view class="segments"><button hover-class="none" v-for="item in [{id:'slide',zh:'滑动',fr:'Glisser'},{id:'page',zh:'翻页',fr:'Tourner'},{id:'none',zh:'关闭',fr:'Aucune'}]" :key="item.id" :class="{active:data.settings.wordMotion===item.id}" @click="setSetting('wordMotion',item.id)"><Bi :zh="item.zh" :fr="item.fr" small /></button></view></view><button hover-class="none" class="toggle-row" @click="setSetting('sounds',data.settings.sounds===false)"><Bi zh="按键与提示音" fr="Sons" small /><view :class="['toggle',{on:data.settings.sounds!==false}]" /></button><view class="setting-row"><Bi zh="每日目标" fr="Objectif quotidien" small /><input :adjust-position="false" class="number-input" type="number" :value="data.settings.dailyGoal" @change="setGoal" aria-label="每日目标 / Objectif quotidien" /></view><button hover-class="none" class="toggle-row" @click="setSetting('fuzzy',!data.settings.fuzzy)"><Bi zh="模糊识别" fr="Réponse tolérante" small /><view :class="['toggle',{on:data.settings.fuzzy}]" /></button></section>
          <section v-else-if="settingsSection==='review'" class="glass settings-card"><button hover-class="none" v-for="item in [{id:'both',zh:'认义＋填空',fr:'Sens + écrit'},{id:'spelling',zh:'只做填空',fr:'Écrit seul'}]" :key="item.id" :class="['review-setting',{selected:data.settings.reviewMode===item.id}]" @click="setSetting('reviewMode',item.id)"><view class="radio"><view v-if="data.settings.reviewMode===item.id" /></view><Bi :zh="item.zh" :fr="item.fr" /></button><button hover-class="none" class="toggle-row" :disabled="!notificationAvailable()" @click="toggleNotifications"><Bi zh="复习提醒" fr="Rappels de révision" small /><view :class="['toggle',{on:data.settings.notifications&&notificationPermission==='granted'}]" /></button><view v-if="data.settings.notifications" class="setting-row"><Bi zh="提醒时间" fr="Heure du rappel" small /><picker mode="time" :value="data.settings.reminderTime||'08:00'" @change="setReminderTime"><button hover-class="none" class="time-choice"><Icon name="clock" /><text>{{ data.settings.reminderTime||'08:00' }}</text><Icon name="chevron-down" /></button></picker></view><view class="setting-row"><Bi zh="复习每天 · 错题每两天" fr="Révision quotidienne · erreurs tous les 2 jours" small /></view><button v-if="nativeHost()" hover-class="none" class="setting-action" @click="openNotificationSettings"><Icon name="settings" /><Bi zh="系统通知设置" fr="Réglages des notifications" small /><Icon name="arrow" /></button><Bi v-if="notificationPermission==='denied'" zh="请允许应用通知" fr="Autorisez les notifications" small /></section>
          <section v-else-if="settingsSection==='data'" class="glass settings-card"><button hover-class="none" class="setting-action" @click="openImport"><Icon name="plus" /><Bi zh="导入课次" fr="Importer" /><Icon name="arrow" /></button><button hover-class="none" class="setting-action" :disabled="busy" @click="backup"><Icon name="download" /><Bi zh="备份（含录音）" fr="Sauvegarder" /><Icon name="arrow" /></button><button hover-class="none" class="setting-action" :disabled="busy" @click="restore"><Icon name="upload" /><Bi zh="恢复备份" fr="Restaurer" /><Icon name="arrow" /></button></section><section v-else class="glass settings-card"><StudyGuide /><view class="manual-about"><text>启航法语 · {{ appManifest.versionName }}</text><text>Cap sur le français</text></view></section></view></Transition>
        </template>
      </main>
      </Transition>
    </view>
    <nav v-if="activeMode==='vocabulary'&&!['practice','recite'].includes(view)" class="mobile-nav glass"><button hover-class="none" v-for="n in navigation" :key="n.id" :class="{active:navActive===n.id}" @click="navigate(n.id)"><Icon :name="n.icon" /><Bi :zh="n.zh" :fr="n.fr" small /><view v-if="n.id==='notebook'&&notebookHasBadge" class="practice-badge" aria-label="有待练词 / À pratiquer" /></button></nav>
