async function startLearningPractice(){if(!requireSelection())return;const s=lessonSession.value;await begin(canContinue(s)?'learn':currentStats.value.practice?'learn':'direct');}
async function toggleLessonPin(p){await commit(d=>{d.pinnedLessons||={};const key=packageKey(p);d.pinnedLessons[key]=!d.pinnedLessons[key];});}
function requestLessonReset(p){if(!p)return;confirmation.value={zh:`将 ${p.lesson.id} 全部放回练习本？`,fr:`Recommencer la leçon ${p.lesson.id} ?`,detail:'本课练习进度将重新开始。 / Les exercices de cette leçon recommenceront.',run:()=>commit(d=>resetLessonProgress(d,p))};}
async function resumeLastPractice(){const last=lastPractice.value;if(!last)return;const {p,session}=last;if(session.lessonKey==='review:all'){selectedSessionKey.value=session.key;const tab=session.mode==='favorites'?'favorites':session.mode==='errors'?'errors':null;if(tab)notebookTab.value=tab;practiceReturnView.value=tab?'notebook':'books';search.value='';view.value='practice';return;}const key=packageKey(p);if(await commit(d=>{d.homeSelection={bookId:p.book.id,lessonKey:key};})){selectedBookId.value=p.book.id;selectedKey.value=key;selectedSessionKey.value=session.key;practiceReturnView.value='books';search.value='';view.value='practice';}}
function openReviewNotebook(){notebookTab.value='review';navigate('notebook');}
function openWordPreview(p,w){reviewDetail.value={p,w,fullPage:true};}
function openMoveDialog(){moveDialog.value=reviewDetail.value;reviewDetail.value=null;}
function backFromPractice(){if(!practicePanel.value?.backToQuestion?.())view.value=practiceReturnView.value;}
function openLesson(p){previewLessonKey.value=packageKey(p);search.value='';view.value='lesson';}
async function begin(mode='learn',ids=null,p=currentPackage.value){practiceReturnView.value=view.value==='recite'?'recite':view.value==='notebook'?'notebook':'books';if(!p)return;const key=sessionKey(p,mode,ids);if(await commit(d=>{startSession(d,p,mode,ids);if(mode==='errors')acknowledgePractice(d,'errors');d.homeSelection={bookId:p.book.id,lessonKey:packageKey(p)};})){selectedBookId.value=p.book.id;selectedKey.value=packageKey(p);selectedSessionKey.value=key;view.value='practice';}}
async function startTodayReview(){if(!dueReviewCount.value&&!hasReviewInProgress.value)return;const from=view.value==='notebook'?'notebook':'books';if(await commit(d=>{startMixedReview(d);acknowledgePractice(d,'review');})){practiceReturnView.value=from;selectedSessionKey.value=MIXED_REVIEW_KEY;search.value='';view.value='practice';}}


async function answer(value,done){const q=currentSession.value?.question;if(!q||busy.value){done?.();return;}await commit(d=>submitAnswer(d,currentPackage.value,q.id,value,undefined,selectedSessionKey.value));done?.();}
async function next(){await commit(d=>advance(d,currentPackage.value,undefined,selectedSessionKey.value));}
async function continuePractice(){await commit(d=>continueRound(d,currentPackage.value,selectedSessionKey.value));}
async function hint(){if(!currentSession.value?.question?.hinted)await commit(d=>revealHint(d,currentPackage.value,selectedSessionKey.value));}
async function retryHint(){await commit(d=>retryAfterHint(d,currentPackage.value,undefined,selectedSessionKey.value));}
async function markKnown(w,done,p=currentPackage.value){await commit(d=>markWordKnown(d,p,w));done?.();}
async function markPreviewKnown(w,done,p){if(p)await commit(d=>markWordKnown(d,p,w));done?.();}
async function favorite(w,p=currentPackage.value){if(!p)return;await commit(d=>{const key=wordKey(p,w);d.favorites[key]=!d.favorites[key];});}
async function play(form){if(!form?.audioKey)return;try{playing.value=form.id;await playAudio(form,repo,()=>playing.value='');}catch(e){playing.value='';if(e.name!=='NotAllowedError')notice(e.message);}}
function stopPlaying(){stopAudio();playing.value='';}
watch(reviewDetail,entry=>{stopPlaying();const form=entry?.w.forms.find(f=>f.audioKey);if(form)play(form);},{flush:'post'});
async function practiceDetail(){const entry=reviewDetail.value;if(entry.errorMode&&errorPracticeState(data.value,entry.p,entry.w,currentDate.value).doneToday){notice('今天已复习 / Déjà révisé aujourd’hui.');return;}reviewDetail.value=null;await begin(entry.errorMode?'errors':'direct',[entry.w.id],entry.p);}
function returnToDefinition(){const entry=moveDialog.value;moveDialog.value=null;if(entry)reviewDetail.value=entry;}
function cancelConfirmation(){const cancel=confirmation.value?.cancel;confirmation.value=null;cancel?.();}
function requestMove(target){const entry=moveDialog.value,{p,w}=entry;moveDialog.value=null;confirmation.value={zh:`将这个词移到${notebookTabs.find(t=>t.id===target).zh}？`,fr:`Déplacer vers « ${notebookTabs.find(t=>t.id===target).fr} » ?`,detail:'仅调整当前 Lesson。 / Pour cette leçon.',cancel:()=>moveDialog.value=entry,run:async()=>{if(await commit(d=>moveWord(d,p,w,target)))reviewDetail.value=entry;}};}
async function confirm(){const action=confirmation.value?.run;confirmation.value=null;if(action)await action();}
async function setSetting(key,value){if(await commit(d=>{d.settings[key]=value;if(key==='errorAutoRemove')for(const session of Object.values(d.sessions))if(session.mode==='errors')session.removeErrors=value!==false;}))notice('偏好已保存 / Préférences enregistrées.');}
async function setGoal(e){const n=Number(e.detail?.value??e.target?.value);if(!Number.isInteger(n)||n<1||n>100){notice('目标应为 1–100 个词 / Objectif entre 1 et 100 mots.');return;}await setSetting('dailyGoal',n);}
function openImportGuide(){const url=new URL('static/使用教程.html#section-4',window.location.href).href;if(nativeHost())window.location.assign(url);else window.open(url,'_blank','noopener');}
function openImport(){importPreview.value=null;importOpen.value=true;}
async function downloadAudioNames(){
  const p=importPreview.value?.pkg;if(!p)return;
  const entries=p.words.flatMap(w=>{
    const grouped=new Map();for(const f of w.forms){const file=f.audio?.split('/').at(-1)||w.sourceAudio||numberedAudioName(w,f)||simpleAudioName(w,f);if(!grouped.has(file))grouped.set(file,[]);grouped.get(file).push(displayForm(w,f));}
    return [...grouped].map(([file,forms])=>[w.audioNumber||'',forms.join(' / '),file]);
  });
  const rows=[['音频编号','法语词条','录音文件'],...entries];
  const escape=value=>{const raw=String(value);return '"'+(/^[=+@-]/.test(raw)?"'"+raw:raw).replaceAll('"','""')+'"';};
  const csv='\uFEFF'+rows.map(row=>row.map(escape).join(',')).join('\r\n');try{await download(`${p.lesson.id}_录音命名清单.csv`,new TextEncoder().encode(csv),'text/csv');}catch(e){if(e.name!=='AbortError')notice(e.message);}
}
async function selectImport(){if(busy.value)return;try{const file=await chooseFile('.zip,.xlsx,.json',true);if(!file?.length)return;busy.value=true;const preview=await parseImport(file,{...importMeta,reservedIds:[...(data.value.reservedWordIds||[]),...Object.keys(data.value.progress).map(k=>k.split(':')[2]),...Object.keys(data.value.favorites).map(k=>k.split(':')[2]),...Object.values(data.value.errors).map(e=>e.wordId)]},data.value.library);const old=data.value.library.find(p=>packageKey(p)===packageKey(preview.pkg));if(old&&!old.demo&&preview.pkg.lesson.version<=old.lesson.version)throw new Error('请选择更高版本的课次包 / Une version plus récente est requise.');importPreview.value=preview;}catch(e){notice(`导入检查 / Vérification : ${e.message}`);}finally{busy.value=false;}}
async function applyImport(){const preview=importPreview.value;if(!preview)return;if(await commit(d=>installLesson(d,clone(preview.pkg)),preview.assets)){importOpen.value=false;importPreview.value=null;openRecitation(preview.pkg);notice('课次已导入 / Leçon importée.');}}
async function backup(){if(busy.value)return;busy.value=true;try{await download(`francais-backup-${day()}.zip`,await exportBackup(clone(data.value),repo),'application/zip');notice('完整备份已导出 / Sauvegarde exportée.');}catch(e){notice(e.message);}finally{busy.value=false;}}
async function restore(){try{const file=await chooseFile('.zip');if(!file)return;busy.value=true;const restored=await readBackup(file);busy.value=false;confirmation.value={zh:'用备份替换当前学习记录？',fr:'Restaurer cette sauvegarde ?',detail:'会替换本机词库、设置及进度，建议先导出当前备份。 / Le contenu local sera remplacé.',run:async()=>{if(await commit(d=>{for(const key of Object.keys(d))delete d[key];Object.assign(d,restored.data);},restored.assets)){navigate('books');notice('备份已恢复 / Sauvegarde restaurée.');}}};}catch(e){notice(e.message);}finally{busy.value=false;}}
watch([view,selectedKey],()=>{stopAudio();playing.value='';if(typeof window!=='undefined')window.scrollTo({top:0,behavior:'instant'});});
let reminderTimer,reviewNotification,reminderChecking=false;
async function startNextLesson(){if(nextLesson.value)await openRecitation(nextLesson.value);else navigate('lessons');}
async function startFavorites(){if(!favoriteWordCount.value&&!hasFavoritesInProgress.value)return;if(await commit(d=>startFavoritePractice(d))){practiceReturnView.value='notebook';selectedSessionKey.value=MIXED_FAVORITES_KEY;view.value='practice';}}
async function startErrors(){if(!errorWordCount.value&&!hasErrorsInProgress.value)return;if(await commit(d=>{startErrorPractice(d);acknowledgePractice(d,'errors');})){practiceReturnView.value='notebook';selectedSessionKey.value=MIXED_ERRORS_KEY;view.value='practice';}}
function reviewCountdown(entry,fr=false){const n=reviewDaysLeft(data.value,entry.p,entry.w,currentDate.value);return n===null?'—':n===0?(fr?'À réviser':'今天复习'):(fr?'Dans '+n+' j':'剩余 '+n+' 天复习');}
async function setReminderTime(e){const value=e.detail?.value;if(/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(value))await setSetting('reminderTime',value);}
async function toggleNotifications(){
  if(data.value.settings.notifications&&notificationPermission.value==='granted'){await setSetting('notifications',false);return;}
  try{notificationPermission.value=await allowNotifications();if(notificationPermission.value==='granted'){await setSetting('notifications',true);checkReviewReminder();}else notice('通知未开启 / Notifications désactivées.');}catch(e){notice(e.message);}
}
async function laterReview(){if(await commit(d=>snoozeReminder(d))){reviewReminderOpen.value=false;reviewNotification?.close();}}
async function reviewNow(){
  reviewReminderOpen.value=false;if(popupReminderCounts.value.review)await startTodayReview();else if(popupReminderCounts.value.errors){notebookTab.value='errors';await startErrors();}
}
async function checkReviewReminder(){
  clockNow.value=Date.now();
  if(!ready.value||busy.value||reminderChecking||(!activeReminderCounts.value.review&&!activeReminderCounts.value.errors))return;
  reminderChecking=true;
  try{
    if(activeMode.value==='vocabulary'&&!modeDrawerOpen.value&&document.visibilityState==='visible'&&shouldRemind(data.value)&&view.value!=='practice'&&!help.value&&!shareOpen.value&&!importOpen.value&&!confirmation.value&&!moveDialog.value&&!drawerOpen.value&&!reviewDetail.value){const counts=popupCounts(data.value);if(await commit(d=>markReminderShown(d))){popupReminderCounts.value=counts;reviewReminderOpen.value=true;}}
    if(data.value.settings.notifications&&shouldNotifyReview(data.value)){
      try{const counts=notificationCounts(data.value);reviewNotification=notifyReview(counts,()=>{notebookTab.value=counts.review?'review':'errors';navigate('notebook');});if(reviewNotification)await commit(d=>markNotificationSent(d,counts));}catch{notice('通知不可用 / Notifications indisponibles.');}
    }
  }finally{reminderChecking=false;}
}
function onVisibility(){if(document.visibilityState==='visible'){notificationPermission.value=getNotificationPermission();syncNativeReview(data.value);checkReviewReminder();}}
function nativeBack(e){if(modeDrawerOpen.value){modeDrawerOpen.value=false;}else if(importOpen.value){importOpen.value=false;importPreview.value=null;}else if(shareOpen.value)shareOpen.value=false;else if(help.value)help.value=null;else if(confirmation.value)cancelConfirmation();else if(reviewDetail.value)reviewDetail.value=null;else if(moveDialog.value)returnToDefinition();else if(drawerOpen.value)drawerOpen.value=false;else if(reviewReminderOpen.value)reviewReminderOpen.value=false;else if(activeMode.value!=='vocabulary')chooseMode('vocabulary');else if(view.value==='practice')backFromPractice();else if(view.value==='lesson')view.value='lessons';else if(view.value==='recite'||view.value==='manuals'||view.value==='lessons')navigate('books');else if(view.value!=='books')navigate('books');else return;e.preventDefault();}
function onNativeReview(event){chooseMode('vocabulary');notebookTab.value=event.detail?.notebook==='errors'?'errors':'review';navigate('notebook');}
function onEscape(e){if(e.key==='Escape'){if(modeDrawerOpen.value)modeDrawerOpen.value=false;else if(help.value)help.value=null;else if(confirmation.value)cancelConfirmation();else if(moveDialog.value)returnToDefinition();else if(drawerOpen.value)drawerOpen.value=false;else if(reviewDetail.value)reviewDetail.value=null;else if(activeMode.value!=='vocabulary')chooseMode('vocabulary');else if(view.value==='practice')backFromPractice();}}
watch(activeReminderCounts,counts=>{if(!counts.review&&!counts.errors)reviewReminderOpen.value=false;});
let stopAccessibility;onMounted(()=>{stopAccessibility=accessibleButtons();load();reminderTimer=setInterval(checkReviewReminder,30000);document.addEventListener('visibilitychange',onVisibility);document.addEventListener('keydown',onEscape);window.addEventListener('qihang-back',nativeBack);window.addEventListener('qihang-review-open',onNativeReview);window.addEventListener('qihang-resume',onVisibility);});
onUnmounted(()=>{stopAccessibility?.();clearTimeout(toastTimer);clearInterval(reminderTimer);reviewNotification?.close();document.removeEventListener('visibilitychange',onVisibility);document.removeEventListener('keydown',onEscape);window.removeEventListener('qihang-back',nativeBack);window.removeEventListener('qihang-review-open',onNativeReview);window.removeEventListener('qihang-resume',onVisibility);stopAudio();});
</script>
